/** One stroke thickness for every formal line generated by the app. */
export const SYSTEM_FORMAL_LINE_THICKNESS_PT = 0.75;
export const SYSTEM_FORMAL_LINE_THICKNESS_EMU = Math.round(SYSTEM_FORMAL_LINE_THICKNESS_PT * 12_700);
export const SYSTEM_FORMAL_LINE_THICKNESS_CSS = SYSTEM_FORMAL_LINE_THICKNESS_PT + "pt";
